def solve():
    n = 120
    max_x1 = 0
    for m in range(1, n + 1):
        # Find the best a such that m*a <= n
        # x1 = m * binom(a, 2) * (binom(n-a, 2) - (m-1) * binom(a, 2))
        for a in range(1, n // m + 1):
            x1 = (m * (a * (a-1) // 2)) * ( (n-a)*(n-a-1)//2 - (m-1) * (a*(a-1)//2) )
            if x1 > max_x1:
                max_x1 = x1
    return max_x1

print(solve())

